import React, { useState } from 'react';
import { Button } from "@/components/ui/button";
import { Sparkles, Loader2, RefreshCw } from 'lucide-react';
import { base44 } from '@/api/base44Client';
import { cn } from "@/lib/utils";

export default function AIReflection({ belief, onSave }) {
  const [isLoading, setIsLoading] = useState(false);
  const [reflection, setReflection] = useState(null);
  const [error, setError] = useState(null);

  const generateReflection = async () => {
    setIsLoading(true);
    setError(null);

    const prompt = `You are a calm, thoughtful reflection assistant. Your role is to help someone think more clearly about their beliefs — NOT to persuade, judge, or argue.

The user has recorded this belief:

BELIEF: "${belief.statement}"

WHY THEY BELIEVE IT: "${belief.reasoning || 'Not specified'}"

EVIDENCE/EXPERIENCES: "${belief.evidence || 'Not specified'}"

CONFIDENCE LEVEL: ${belief.confidence}/10

WHAT WOULD CHANGE THEIR MIND: "${belief.what_would_change || 'Not specified'}"

Please provide a brief, gentle reflection that:
1. Summarizes their belief in neutral language (1-2 sentences)
2. Asks 1-2 clarifying questions that might help them think deeper
3. Gently highlights any assumptions you notice (if any)

Keep your tone warm, curious, and non-judgmental. Be concise — this is for mobile reading. Do not try to change their mind or offer your own opinion.`;

    try {
      const response = await base44.integrations.Core.InvokeLLM({
        prompt,
        response_json_schema: {
          type: "object",
          properties: {
            summary: {
              type: "string",
              description: "A neutral 1-2 sentence summary of their belief"
            },
            clarifying_questions: {
              type: "array",
              items: { type: "string" },
              description: "1-2 gentle clarifying questions"
            },
            assumptions_noticed: {
              type: "string",
              description: "Any assumptions gently highlighted, or empty if none obvious"
            }
          }
        }
      });

      setReflection(response);
    } catch (err) {
      setError("Couldn't generate reflection. You can try again later.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!reflection) return;

    const newAiReflection = {
      date: new Date().toISOString(),
      content: JSON.stringify(reflection)
    };

    const existingReflections = belief.ai_reflections || [];
    await onSave({
      ai_reflections: [...existingReflections, newAiReflection]
    });
  };

  if (!reflection && !isLoading) {
    return (
      <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6">
        <div className="flex items-start gap-3">
          <div className="w-10 h-10 rounded-xl bg-white/80 flex items-center justify-center flex-shrink-0">
            <Sparkles className="w-5 h-5 text-[#5C6B5E]" />
          </div>
          <div className="flex-1">
            <h3 className="font-medium text-slate-800 mb-1">AI Reflection</h3>
            <p className="text-sm text-slate-600 mb-4">
              Get a gentle reflection to help clarify your thinking. The AI won't judge or try to change your mind.
            </p>
            <Button
              onClick={generateReflection}
              disabled={isLoading}
              className="bg-white hover:bg-slate-50 text-[#5C6B5E] border border-[#5C6B5E]/20 rounded-xl"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              Reflect with AI
            </Button>
          </div>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6">
        <div className="flex items-center justify-center gap-3 py-8">
          <Loader2 className="w-5 h-5 animate-spin text-[#5C6B5E]" />
          <span className="text-slate-600">Thinking gently...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 rounded-2xl p-6">
        <p className="text-red-600 text-sm mb-3">{error}</p>
        <Button
          onClick={generateReflection}
          variant="outline"
          size="sm"
          className="text-red-600 border-red-200"
        >
          <RefreshCw className="w-4 h-4 mr-2" />
          Try again
        </Button>
      </div>
    );
  }

  return (
    <div className="bg-gradient-to-br from-[#E8EDE9] to-[#f0f4f1] rounded-2xl p-6 space-y-4">
      <div className="flex items-center gap-2">
        <Sparkles className="w-4 h-4 text-[#5C6B5E]" />
        <span className="text-sm font-medium text-[#5C6B5E]">AI Reflection</span>
      </div>

      {/* Summary */}
      {reflection.summary && (
        <div>
          <p className="text-sm text-slate-500 mb-1">In other words:</p>
          <p className="text-slate-700 leading-relaxed">{reflection.summary}</p>
        </div>
      )}

      {/* Questions */}
      {reflection.clarifying_questions?.length > 0 && (
        <div>
          <p className="text-sm text-slate-500 mb-2">Questions to consider:</p>
          <ul className="space-y-2">
            {reflection.clarifying_questions.map((q, i) => (
              <li key={i} className="flex gap-2 text-slate-700">
                <span className="text-[#5C6B5E]">•</span>
                <span className="leading-relaxed">{q}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Assumptions */}
      {reflection.assumptions_noticed && (
        <div>
          <p className="text-sm text-slate-500 mb-1">Possible assumptions:</p>
          <p className="text-slate-700 leading-relaxed">{reflection.assumptions_noticed}</p>
        </div>
      )}

      <div className="flex gap-2 pt-2">
        <Button
          onClick={generateReflection}
          variant="outline"
          size="sm"
          className="text-slate-600 border-slate-200 rounded-lg"
        >
          <RefreshCw className="w-4 h-4 mr-1" />
          New reflection
        </Button>
        <Button
          onClick={handleSave}
          size="sm"
          className="bg-[#5C6B5E] hover:bg-[#4a574c] text-white rounded-lg"
        >
          Save this
        </Button>
      </div>
    </div>
  );
}
